import Foundation

extension ReaderStore {
    /// Resolve on each render, so choosing a language takes effect immediately.
    func t(_ chinese: String) -> String {
        ReaderUIStrings.text(chinese, language: library.settings.language)
    }
}

/// The Chinese source string is a stable key. Application-owned UI text has a
/// complete catalog; unknown external errors are left intact rather than altered.
enum ReaderUIStrings {
    static let translatedLanguages: [ReaderLanguage] = [.ja, .ko, .fr, .de, .es, .pt]
    static var keys: Set<String> { Set(english.keys) }
    static func text(_ chinese: String, english fallback: String? = nil, language: ReaderLanguage) -> String {
        let resolved = language.resolved()
        if resolved == .zhHans { return chinese }
        if resolved == .zhHant { return traditional[chinese] ?? toTraditional(chinese) }
        if let exact = translation(chinese, language: resolved) { return exact }
        // Numeric labels are formatted as complete sentences in each language.
        // Do not translate digits or splice independently translated fragments.
        for key in numericTemplates {
            let parts = key.components(separatedBy: "{0}")
            guard parts.count == 2, chinese.hasPrefix(parts[0]), chinese.hasSuffix(parts[1]),
                  chinese.count >= parts[0].count + parts[1].count else { continue }
            let number = String(chinese.dropFirst(parts[0].count).dropLast(parts[1].count))
            guard !number.isEmpty, number.allSatisfy({ $0 >= "0" && $0 <= "9" }),
                  let format = translation(key, language: resolved) else { continue }
            return format.replacingOccurrences(of: "{0}", with: number)
        }
        for prefix in ["暂时无法恢复登录，已保留钥匙串中的凭据。"] where chinese.hasPrefix(prefix) {
            if let translated = translation(prefix, language: resolved) {
                return translated + " " + String(chinese.dropFirst(prefix.count))
            }
        }
        return fallback ?? chinese
    }
    static func translation(_ key: String, language: ReaderLanguage) -> String? {
        switch language.resolved() {
        case .zhHans: return keys.contains(key) ? key : nil
        case .zhHant: return traditional[key]
        case .en: return english[key]
        default:
            guard let index = translatedLanguages.firstIndex(of: language.resolved()), let row = translations[key], row.indices.contains(index) else { return nil }
            return row[index]
        }
    }
    private static func toTraditional(_ value: String) -> String {
        value.applyingTransform(StringTransform("Hans-Hant"), reverse: false) ?? value
    }
    private static let traditional: [String: String] = Dictionary(uniqueKeysWithValues: english.keys.map { ($0, toTraditional($0)) })
    private static let numericTemplates = english.keys.filter { $0.contains("{0}") }.sorted { $0.count > $1.count }
